import { copyFileSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { afterAll, describe, expect, it } from 'vitest';

import { readPackages } from '../src/rules/dependencies';
import { sourceOf } from '../src/rules/js-lockfiles';

/*
 * Real lockfiles for the JavaScript edge cases, each generated by the package manager itself from
 * the package.json beside it: npm 11, pnpm 10 (lockfile v9), Yarn 1.22 and Yarn 4.5.
 *   sources-*      lodash and ms from the registry (ms by its registry tarball URL), is-number from
 *                  GitHub at a commit, escape-string-regexp from a GitHub archive, shared from ./shared
 *   overrides-*    mkdirp 0.5.5, with minimist forced to 1.2.8 (npm overrides, pnpm.overrides, Yarn resolutions)
 *   catalog-pnpm   lodash from the default catalog, minimist (dev) from a named one
 *   workspaces-*   npm and Yarn workspaces: api has lodash, and minimist and is-number as dev dependencies;
 *                  web has ms and is-number
 */
const EDGE = join(__dirname, 'fixtures', 'lockfiles', 'edge');
const LOCKFILE = { npm: 'package-lock.json', pnpm: 'pnpm-lock.yaml', yarn1: 'yarn.lock', berry: 'yarn.lock' } as const;
type Tool = keyof typeof LOCKFILE;

const read = (dir: string, tool: Tool) => readPackages(join(EDGE, dir), [LOCKFILE[tool], 'package.json']);
const listed = (dir: string, tool: Tool) =>
  read(dir, tool)
    .packages.map((p) => `${p.name}@${p.version}${p.dev ? ' (dev)' : ''}`)
    .sort();

describe('packages from git, tarballs and local folders', () => {
  for (const tool of ['npm', 'pnpm', 'yarn1', 'berry'] as const) {
    it(`${tool}: names them in the note instead of checking them as registry releases`, () => {
      const r = read(`sources-${tool}`, tool);
      // ms comes by URL, but it's the registry's own tarball, so it's still a registry release.
      expect(r.packages.map((p) => `${p.name}@${p.version}`).sort()).toEqual(['lodash@4.17.15', 'ms@2.1.3']);
      expect(r.notes.join('\n')).toContain('3 dependencies have no exact version');
      expect(r.notes.join('\n')).toContain(`${LOCKFILE[tool]}: escape-string-regexp (tarball), is-number (git), shared (local folder).`);
    });
  }

  it("tells sources apart, and leaves registries and workspaces alone", () => {
    expect(sourceOf('git+ssh://git@github.com/a/b.git#abc')).toBe('git');
    expect(sourceOf('github:a/b#abc')).toBe('git');
    expect(sourceOf('a/b#abc')).toBe('git');
    expect(sourceOf(`https://codeload.github.com/a/b/tar.gz/${'f'.repeat(40)}`)).toBe('git');
    expect(sourceOf('https://github.com/a/b/archive/refs/tags/v1.0.0.tar.gz')).toBe('tarball');
    expect(sourceOf('https://cdn.example.com/b-1.0.0.tgz')).toBe('tarball');
    expect(sourceOf('file:../lib')).toBe('local');
    expect(sourceOf('portal:./lib')).toBe('local');
    expect(sourceOf('https://registry.npmjs.org/ms/-/ms-2.1.3.tgz')).toBeUndefined();
    expect(sourceOf('https://npm.pkg.github.com/download/@acme/b/1.0.0/abc')).toBeUndefined(); // a private registry
    expect(sourceOf('workspace:*')).toBeUndefined();
    expect(sourceOf('link:../web')).toBeUndefined();
    expect(sourceOf('npm:4.17.15')).toBeUndefined();
  });
});

describe('npm overrides and Yarn or pnpm resolutions', () => {
  for (const [dir, tool] of [['overrides-npm', 'npm'], ['overrides-pnpm', 'pnpm'], ['resolutions-yarn1', 'yarn1'], ['resolutions-berry', 'berry']] as const) {
    it(`${dir}: checks the forced version, as production`, () => {
      expect(listed(dir, tool)).toEqual(['minimist@1.2.8', 'mkdirp@0.5.5']);
    });
  }
});

describe('pnpm catalogs', () => {
  it('reads packages pinned through the default and named catalogs, with the dev split', () => {
    expect(listed('catalog-pnpm', 'pnpm')).toEqual(['lodash@4.17.15', 'minimist@1.2.5 (dev)']);
  });
});

describe('Yarn workspaces', () => {
  for (const tool of ['yarn1', 'berry'] as const) {
    it(`${tool}: works out dev-only packages from each workspace's own package.json`, () => {
      // is-number is a dev dependency of api but a production one of web, so it's production.
      expect(listed(`workspaces-${tool}`, tool)).toEqual(['is-number@7.0.0', 'lodash@4.17.15', 'minimist@1.2.5 (dev)', 'ms@2.1.3']);
    });
  }

  it("npm: gives the same split, and doesn't list its own workspaces as local folders", () => {
    const r = read('workspaces-npm', 'npm');
    expect(listed('workspaces-npm', 'npm')).toEqual(['is-number@7.0.0', 'lodash@4.17.15', 'minimist@1.2.5 (dev)', 'ms@2.1.3']);
    expect(r.notes).toEqual([]);
  });
});

describe('more than one lockfile in a folder', () => {
  const dirs: string[] = [];
  afterAll(() => dirs.forEach((d) => rmSync(d, { recursive: true, force: true })));

  const mixed = (packageJson: object) => {
    const dir = mkdtempSync(join(tmpdir(), 'fortis-mixed-'));
    dirs.push(dir);
    copyFileSync(join(EDGE, 'overrides-npm', 'package-lock.json'), join(dir, 'package-lock.json'));
    copyFileSync(join(EDGE, 'catalog-pnpm', 'pnpm-lock.yaml'), join(dir, 'pnpm-lock.yaml'));
    writeFileSync(join(dir, 'package.json'), JSON.stringify(packageJson));
    return readPackages(dir, ['package-lock.json', 'pnpm-lock.yaml', 'package.json']);
  };

  it("uses the lockfile package.json's packageManager names, and says so", () => {
    const r = mixed({ packageManager: 'npm@11.7.0' });
    expect(r.packages.map((p) => p.name).sort()).toEqual(['minimist', 'mkdirp']);
    expect(r.notes).toContain("The repository root has more than one lockfile: checked package-lock.json (package.json's packageManager says npm), not pnpm-lock.yaml. Delete the one you don't use.");
  });

  it("otherwise prefers pnpm's, since a stray npm lockfile is the usual mix-up", () => {
    const r = mixed({});
    expect(r.packages.map((p) => p.name).sort()).toEqual(['lodash', 'minimist']);
    expect(r.notes).toContain("The repository root has more than one lockfile: checked pnpm-lock.yaml (package-lock.json next to it is usually left over), not package-lock.json. Delete the one you don't use.");
  });
});
